CREATE OR REPLACE FUNCTION get_grpart_infos (_grId uuid, _lang TEXT)
RETURNS TABLE (
          part jsonb
      ) AS $$

BEGIN

RETURN QUERY
    select to_jsonb(json_agg(n)) from (select get_grpart_info(_grId, _lang, position) as part_info from georegulation_part where georegulation_id = _grId order by position) as n;


END; $$
LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_gr_with_allinfoparts (_grType VARCHAR, _lang TEXT) RETURNS TABLE ( grId uuid, grType TEXT, grNumber TEXT, grActivity TEXT, grTitle TEXT, grSummary TEXT, grTemporary boolean, grNew boolean, grCoastlineLimit boolean, grPublic boolean, grArea TEXT, grDate jsonb, grSeasonalPeriod TEXT, grPartId uuid, grPartPosition INTEGER, parts jsonb, grLink TEXT, language TEXT, publicationDate TEXT, geom geometry ) AS $$
BEGIN
RETURN QUERY select distinct gr.id as grId, case _lang when 'fr' THEN string_agg(distinct grTypesTranslation.translation, ', ') when 'en' THEN string_agg(distinct grTypesTranslation.international_translation, ', ') END as grType, gr.number_year || COALESCE('-' || gr.number_text, '') || COALESCE('-' || string_agg(distinct grAuthorityCode.authority_code, ' '), '') || COALESCE('-' || to_char(gr.number_date, 'DDMMYYYY'), '') as grNumber, case _lang when 'fr' THEN string_agg(distinct grActivityTranslation.translation, ', ') when 'en' THEN string_agg(distinct grActivityTranslation.international_translation, ', ') END as grActivity, gr.title as grTitle, gr.summary as grSummary, gr.is_temporary as grTemporary, gr.is_new as grNew, gr.has_coastline_limit as grCoastlineLimit, gr.is_public as grPublic, string_agg(distinct grArea.name, ',') as grArea, to_jsonb(json_agg(distinct jsonb_build_object('position', grDate.position, 'date_start', to_char(grDate.date_start, 'DD/MM/YYYY'), 'date_end', to_char(grDate.date_end, 'DD/MM/YYYY')))) as grDate, string_agg(distinct concat(grSeasonPeriod.day_start, '/', grSeasonPeriod.month_start, '-', grSeasonPeriod.day_end, '/', grSeasonPeriod.month_end), ',') as grSeasonalPeriod, grPart.id as grPartId, grPart.position as grPartPosition, (select get_grpart_infos(gr.id, _lang)) as parts, json_agg(distinct grLink.link)::text as grLink, _lang, to_char(gr.publication_date, 'DD/MM/YYYY') as publicationDate, grPartFeature.geom as geom from georegulation_part as grPart left join georegulation as gr on gr.id = grPart.georegulation_id left join georegulation_activity as grActivity on grActivity.georegulation_id = gr.id left join georegulation_activities as grActivityTranslation on grActivityTranslation.enum_name = grActivity.activity left join georegulation_types as grTypesTranslation on grTypesTranslation.enum_name = gr.type left join georegulation_link as grLink on grLink.georegulation_id = gr.id left join georegulation_number_authority_code as grAuthorityCode on grAuthorityCode.georegulation_id = gr.id left join georegulation_seasonal_period as grSeasonPeriod on grSeasonPeriod.georegulation_id = gr.id left join fixed_date_range as grDate on grDate.parent_id=gr.id left join georegulation_part_feature as grPartFeature on grPartFeature.part_id = grPart.id left join maritime_service as grService on grService.id=gr.issuing_service_id left join maritime_service_areas as grServiceArea on grService.id=grServiceArea.maritime_service_id left join area as grArea on grArea.id=grServiceArea.areas_id where gr.type=_grType and gr.status='PUBLISHED' and gr.is_public is true and gr.is_expired is false group by gr.id, grPart.id, grPartFeature.geom; END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_anpart_info (_warningId uuid, _lang TEXT, _defaultLang TEXT, _partPosition INTEGER) RETURNS TABLE ( featurePartId uuid, featurePartWarningHazardTypeDetails TEXT, featurePartInformation TEXT, featurePartDateRange jsonb ) AS $$
BEGIN
RETURN QUERY (select distinct part.id as featurePartId, case _lang when 'fr' THEN string_agg(distinct type_details.translation, ',') when 'en' THEN string_agg(distinct type_details.international_translation, ',') end featurePartWarningHazardTypeDetails, case when (part_text.text is not null) THEN part_text.text ELSE default_part_text.text END as featurePartInformation, to_jsonb(json_agg(distinct jsonb_build_object('position', part_date.position, 'date_start', part_date.date_start, 'time_of_day_start', part_date.time_of_day_start+'1 hour', 'date_end', part_date.date_end, 'time_of_day_end', part_date.time_of_day_end+'1 hour'))) as featurePartDateRange from warning_feature_part as part left join warning as w on part.warning_id=w.id left join warning_feature_part_warning_hazard_type_details as part_type on part_type.feature_part_id = part.id left join localized_text as part_text on part_text.parent_id=part.id and part_text.language=_lang left join localized_text as default_part_text on default_part_text.parent_id=part.id and default_part_text.language=_defaultLang left join fixed_date_range as part_date on part_date.parent_id=part.id left join warning_hazard_type_details as type_details on type_details.enum_name=part_type.warning_hazard_type_detail where w.id = _warningId and part.position=_partPosition group by w.id, part.id, featurePartInformation ); END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_anpart_infos (_warningId uuid, _lang TEXT, _defaultLang TEXT)
RETURNS TABLE (
          part jsonb
      ) AS $$

BEGIN

RETURN QUERY
select to_jsonb(json_agg(n)) from (select get_anpart_info(_warningId, _lang, _defaultLang, position) as part_info from warning_feature_part where warning_id = _warningId order by position) as n;


END; $$
LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_an_cancelled (_warningId uuid) RETURNS TABLE ( cancelled jsonb ) AS $$
BEGIN
RETURN QUERY select to_jsonb(json_agg(distinct jsonb_build_object('warning_id', w.id, 'name_of_series', w.name_of_series, 'warning_number', w.warning_number, 'year', w.year))) from warning_reference as warn_ref left join warning_reference_warning as warn_ref_warn on warn_ref.id=warn_ref_warn.warning_reference_id left join warning as w on warn_ref_warn.warning_id=w.id where warn_ref.category='CANCELLATION' and warn_ref.warning_id=_warningId;
END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_an_with_allinfoparts (_lang TEXT, _defaultLang TEXT = 'fr') RETURNS TABLE ( warningId uuid, warningType VARCHAR, nameOfSeries VARCHAR, warningNumber INTEGER, year INTEGER, generalArea TEXT, locality TEXT, warningHazardTypeGeneral TEXT, publicationDate TEXT, cancellationDate TEXT, language TEXT, productionAgency VARCHAR, country VARCHAR, featurePartId uuid, featurePartPosition INTEGER, parts jsonb, cancelledWarnings jsonb, type TEXT, geom geometry ) AS $$
BEGIN
RETURN QUERY (select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct locality_text.text, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'geom' as type, part_geom.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality as w_locality on w.id=w_locality.warning_id left join localized_text as locality_text on w_locality.id=locality_text.parent_id and locality_text.language=_lang left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general left join warning_feature_part_geometry as part_geom on part_geom.feature_part_id=part.id where w.status='PUBLISHED' group by w.id, s.type, part.id, part.position, part_geom.geom order by w.id ) UNION ( select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct locality_text.text, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'affected_area' as type, part_affectedarea.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality as w_locality on w.id=w_locality.warning_id left join localized_text as locality_text on w_locality.id=locality_text.parent_id and locality_text.language=_lang left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general inner join warning_feature_part_affected_area as part_affectedarea on part_affectedarea.feature_part_id=part.id where w.status='PUBLISHED' group by w.id, s.type, part.id, part.position, part_affectedarea.geom order by w.id ); END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_an_with_allinfoparts_for_serie (_nameOfSerie VARCHAR, _lang TEXT, _defaultLang TEXT = 'fr') RETURNS TABLE ( warningId uuid, warningType VARCHAR, nameOfSeries VARCHAR, warningNumber INTEGER, year INTEGER, generalArea TEXT, locality TEXT, warningHazardTypeGeneral TEXT, publicationDate TEXT, cancellationDate TEXT, language TEXT, productionAgency VARCHAR, country VARCHAR, featurePartId uuid, featurePartPosition INTEGER, parts jsonb, cancelledWarnings jsonb, type TEXT, geom geometry ) AS $$
BEGIN
RETURN QUERY (select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct locality_text.text, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'geom' as type, part_geom.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality as w_locality on w.id=w_locality.warning_id left join localized_text as locality_text on w_locality.id=locality_text.parent_id and locality_text.language=_lang left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general left join warning_feature_part_geometry as part_geom on part_geom.feature_part_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part.position, part_geom.geom order by w.id ) UNION ( select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct locality_text.text, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'affected_area' as type, part_affectedarea.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality as w_locality on w.id=w_locality.warning_id left join localized_text as locality_text on w_locality.id=locality_text.parent_id and locality_text.language=_lang left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general inner join warning_feature_part_affected_area as part_affectedarea on part_affectedarea.feature_part_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part.position, part_affectedarea.geom order by w.id ); END; $$ LANGUAGE 'plpgsql';
